-- Draft PostgreSQL persistence contract for the offline review foundation.
-- NOT a deployed migration; it has not been executed against PostgreSQL or Aiven.
-- A future backend must authenticate the workspace, authorize workbook access, use
-- parameterized queries, cap request bodies, and wrap each resume/save in a transaction.
-- All UUIDs are generated by that backend; no PostgreSQL extension is required.

BEGIN;

CREATE TABLE review_sales (
    workspace_id uuid NOT NULL,
    record_id text NOT NULL CHECK (octet_length(record_id) BETWEEN 1 AND 256),
    category text NOT NULL CHECK (octet_length(category) BETWEEN 1 AND 256),
    ordered_at timestamptz NOT NULL,
    amount_minor bigint NOT NULL CHECK (amount_minor BETWEEN 0 AND 1000000000000),
    refunded_minor bigint NOT NULL CHECK (refunded_minor BETWEEN 0 AND amount_minor),
    currency text NOT NULL CHECK (currency = 'EUR'),
    status text NOT NULL CHECK (status IN ('paid', 'pending', 'cancelled')),
    is_test boolean NOT NULL DEFAULT false,
    PRIMARY KEY (workspace_id, record_id)
);
CREATE INDEX review_sales_period ON review_sales (workspace_id, ordered_at)
    WHERE status = 'paid';

CREATE TABLE review_rules (
    workspace_id uuid NOT NULL,
    rule_id text NOT NULL CHECK (octet_length(rule_id) BETWEEN 1 AND 256),
    original_wording text NOT NULL CHECK (octet_length(original_wording) BETWEEN 1 AND 256),
    kind text NOT NULL CHECK (kind = 'exclude_test_orders'),
    enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, rule_id)
);

CREATE TABLE review_workbooks (
    workspace_id uuid NOT NULL,
    workbook_id uuid NOT NULL,
    title text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, workbook_id)
);

CREATE TABLE review_snapshots (
    workspace_id uuid NOT NULL,
    workbook_id uuid NOT NULL,
    -- Database version is independent of the browser's session-local change token.
    snapshot_version bigint NOT NULL CHECK (snapshot_version > 0),
    export_id text NOT NULL CHECK (octet_length(export_id) BETWEEN 1 AND 256),
    workbook_session_id text NOT NULL CHECK (octet_length(workbook_session_id) BETWEEN 1 AND 256),
    exported_change_token jsonb NOT NULL CHECK (jsonb_typeof(exported_change_token) = 'object'),
    xlsx bytea NOT NULL CHECK (octet_length(xlsx) BETWEEN 1 AND 52428800),
    -- Calculated by the service from xlsx, not trusted from a client assertion.
    sha256 bytea NOT NULL CHECK (octet_length(sha256) = 32),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, workbook_id, snapshot_version),
    UNIQUE (workspace_id, workbook_id, workbook_session_id, export_id),
    FOREIGN KEY (workspace_id, workbook_id)
        REFERENCES review_workbooks (workspace_id, workbook_id)
);
-- Lock the workbook row while allocating snapshot_version. On duplicate session/export_id,
-- compare session/token/hash/bytes with the stored row before returning the old receipt.
-- Acknowledge export_id + exported_change_token only after COMMIT succeeds. The live
-- browser must keep later edits dirty; latest version is MAX(snapshot_version).

CREATE TABLE review_runs (
    workspace_id uuid NOT NULL,
    run_id uuid NOT NULL,
    workbook_id uuid NOT NULL,
    workbook_session_id text NOT NULL CHECK (octet_length(workbook_session_id) BETWEEN 1 AND 256),
    -- A retry of /start must find this same run and compare start_request exactly.
    client_request_id text NOT NULL CHECK (octet_length(client_request_id) BETWEEN 1 AND 256),
    start_request jsonb NOT NULL CHECK (jsonb_typeof(start_request) = 'object'),
    status text NOT NULL CHECK (status IN ('thinking', 'awaiting_tool', 'provider_timeout', 'complete')),
    conversation jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(conversation) = 'array'),
    -- Record the enabled rules used for the run; changing saved rules must not silently
    -- alter an already-issued query's provenance.
    rule_context jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(rule_context) = 'array'),
    final_response text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, run_id),
    UNIQUE (workspace_id, client_request_id),
    FOREIGN KEY (workspace_id, workbook_id)
        REFERENCES review_workbooks (workspace_id, workbook_id)
);

CREATE TABLE review_tool_calls (
    workspace_id uuid NOT NULL,
    run_id uuid NOT NULL,
    tool_use_id text NOT NULL CHECK (octet_length(tool_use_id) BETWEEN 1 AND 256),
    tool_name text NOT NULL,
    request jsonb NOT NULL CHECK (jsonb_typeof(request) = 'object'),
    status text NOT NULL CHECK (status IN ('outstanding', 'completed')),
    -- The result records success OR failure, including partial effects, as returned by
    -- the validated browser bridge. A provider timeout does not erase this evidence.
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    PRIMARY KEY (workspace_id, run_id, tool_use_id),
    FOREIGN KEY (workspace_id, run_id) REFERENCES review_runs (workspace_id, run_id),
    CHECK ((status = 'outstanding' AND result IS NULL AND completed_at IS NULL)
        OR (status = 'completed' AND result IS NOT NULL AND completed_at IS NOT NULL))
);
-- The initial state machine deliberately permits only one outstanding browser tool.
CREATE UNIQUE INDEX review_one_outstanding_tool
    ON review_tool_calls (workspace_id, run_id) WHERE status = 'outstanding';

CREATE TABLE review_queries (
    workspace_id uuid NOT NULL,
    query_id uuid NOT NULL,
    run_id uuid NOT NULL,
    -- Persist the exact periods, metric, rule ids, record counts and query result to
    -- distinguish reproducible run evidence from today's potentially changed records.
    provenance jsonb NOT NULL CHECK (jsonb_typeof(provenance) = 'object'),
    result jsonb NOT NULL CHECK (jsonb_typeof(result) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, query_id),
    FOREIGN KEY (workspace_id, run_id) REFERENCES review_runs (workspace_id, run_id)
);

COMMIT;

-- Query semantics for the future parameterized repository:
--   workspace_id = $1
--   ordered_at >= $period_start AND ordered_at < $period_end
--   status = 'paid' AND currency = 'EUR'
--   AND (NOT $exclude_tests OR NOT is_test)
--   GROUP BY category; SUM(amount_minor - refunded_minor), COUNT(*)
-- $exclude_tests comes from enabled structured rules, never model-generated SQL.
-- Both weeks must be full consecutive Monday-to-Monday UTC weeks. Read source rows
-- and rule context consistently; reject over-limit results rather than truncating an
-- aggregate. Preserve fully refunded rows in qualifying counts (net revenue is zero).
-- Run row locking and an ownership/session check precede every continuation. An exact
-- completed tool-use id/result replay returns the stored response, without dispatching
-- the tool again; a different payload with the same id is a conflict.
